def specialFilter(nums):
    def is_first_and_last_digit_odd(n):
        if n < 0:
            n = -n
        first_digit = n
        while first_digit >= 10:
            first_digit //= 10
        last_digit = n % 10
        return first_digit % 2 != 0 and last_digit % 2 != 0

    count = 0
    for num in nums:
        if num > 10 and is_first_and_last_digit_odd(num):
            count += 1
    return count

